import { createPushGate } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/knock-inv-g2-1/bot.mjs";
import assert from "node:assert/strict";
const u = { id: "u1", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
const d = (s) => new Date(s);
const r = (g, x, t) => g.attempt(x, d(t));
let g = createPushGate();
// Tokyo = UTC+9. 12:00Z = 21:00 JST allowed; 13:00Z = 22:00 JST quiet; 21:59Z=06:59 quiet; 22:00Z=07:00 ok
assert.equal(r(g,u,"2026-05-01T12:00:00Z").allowed, true);
assert.equal(r(g,u,"2026-05-01T13:00:00Z").reason, "quiet_hours");
assert.equal(r(g,u,"2026-05-01T21:59:00Z").reason, "quiet_hours");
assert.equal(r(g,u,"2026-05-01T22:00:00Z").allowed, true);
// cap: 2 sent so far on JST May 2 (22:00Z = May 2 07:00). Add one more, then capped.
assert.equal(r(g,u,"2026-05-02T01:00:00Z").allowed, true);
assert.deepEqual(r(g,u,"2026-05-02T02:00:00Z"), {allowed:false, reason:"daily_cap_reached"});
// local midnight reset: 14:59Z May 2 = 23:59 JST quiet; use user w/o wrap quiet
const v = { ...u, id:"u2", quietStart:"01:00", quietEnd:"06:00", dailyCap:1 };
g = createPushGate();
assert.equal(r(g,v,"2026-05-02T14:30:00Z").allowed, true); // 23:30 JST May 2
assert.equal(r(g,v,"2026-05-02T14:50:00Z").reason, "daily_cap_reached");
assert.equal(r(g,v,"2026-05-02T15:10:00Z").allowed, true); // 00:10 JST May 3, new day (still UTC May 2)
// blocked don't count
g = createPushGate();
const w = { ...u, id:"u3", dailyCap:1 };
r(g,w,"2026-05-01T13:00:00Z");
assert.equal(r(g,w,"2026-05-01T22:00:00Z").allowed, true);
// DST: New York spring forward 2026-03-08
const ny = { id:"n", timeZone:"America/New_York", quietStart:"23:00", quietEnd:"06:00", dailyCap:5 };
assert.equal(r(createPushGate(),ny,"2026-03-08T06:30:00Z").reason, "quiet_hours"); // 01:30 EST
assert.equal(r(createPushGate(),ny,"2026-03-08T10:30:00Z").allowed, true); // 06:30 EDT
assert.equal(r(createPushGate(),ny,"2026-03-08T09:30:00Z").reason, "quiet_hours"); // 05:30 EDT
// same-day window, equal window, cap 0, invalid
assert.equal(r(createPushGate(),{...ny,quietStart:"13:00",quietEnd:"15:00"},"2026-06-01T18:00:00Z").reason,"quiet_hours");
assert.equal(r(createPushGate(),{...ny,quietStart:"08:00",quietEnd:"08:00"},"2026-06-01T12:00:00Z").allowed,true);
assert.equal(r(createPushGate(),{...ny,dailyCap:0},"2026-06-01T18:00:00Z").reason,"daily_cap_reached");
assert.equal(r(createPushGate(),{...ny,timeZone:"Nope/Zone"},"2026-06-01T18:00:00Z").reason,"invalid_settings");
assert.equal(r(createPushGate(),{...ny,quietStart:"25:00"},"2026-06-01T18:00:00Z").reason,"invalid_settings");
// independence
const a = createPushGate(), b = createPushGate();
const one = {...ny, dailyCap:1};
a.attempt(one, d("2026-06-01T18:00:00Z"));
assert.equal(b.attempt(one, d("2026-06-01T18:30:00Z")).allowed, true);
// per-call settings: raise cap
assert.equal(a.attempt({...one,dailyCap:2}, d("2026-06-01T19:00:00Z")).allowed, true);
console.log("ok");
